             * against small read overruns. */
            if (KRB5_UTF8_CHARLEN(s + i) > len - i) {
                retval = KRB5_ERR_INVALID_UTF8;
                goto cleanup;
            }
            clen = KRB5_UTF8_CHARLEN2(s + i, clen);
            if (clen == 0) {
                retval = KRB5_ERR_INVALID_UTF8;
                goto cleanup;
            }
            if (clen == 1) {
                /* ascii */
                break;
            }
            *p = s[i] & mask[clen];
            i++;
            for (j = 1; j < clen; j++) {
                if ((s[i] & 0xc0) != 0x80) {
                    retval = KRB5_ERR_INVALID_UTF8;
                    goto cleanup;
                }
                *p <<= 6;
                *p |= s[i] & 0x3f;
                i++;
            }
            if (casefold) {
                *p = uctolower(*p);
            }
            p++;
